/**
 * Popup Script
 * 处理弹出窗口的 UI 逻辑
 */

interface ContentStatus {
  isEnabled: boolean;
  isProcessing: boolean;
  isInitialized: boolean;
  processedCount: number;
  isJapanesePage: boolean;
  colorMode: boolean;
}

// DOM 元素
const toggleCheckbox = document.getElementById('enableToggle') as HTMLInputElement;
const colorModeCheckbox = document.getElementById('colorModeToggle') as HTMLInputElement;
const statusElement = document.getElementById('status') as HTMLDivElement;
const lookupInput = document.getElementById('lookupInput') as HTMLInputElement;
const lookupBtn = document.getElementById('lookupBtn') as HTMLButtonElement;
const lookupResult = document.getElementById('lookupResult') as HTMLDivElement;
const reverseInput = document.getElementById('reverseInput') as HTMLInputElement;
const reverseBtn = document.getElementById('reverseBtn') as HTMLButtonElement;
const reverseResult = document.getElementById('reverseResult') as HTMLDivElement;

// 读音字典缓存
let readingDict: Record<string, string[]> | null = null;

// 当前状态
let currentStatus: ContentStatus | null = null;

/**
 * 更新状态显示
 */
function updateStatusDisplay(status: ContentStatus | null, error?: string): void {
  if (error) {
    statusElement.textContent = error;
    statusElement.className = 'status inactive';
    toggleCheckbox.disabled = true;
    colorModeCheckbox.disabled = true;
    return;
  }

  if (!status) {
    statusElement.textContent = '読み込み中...';
    statusElement.className = 'status';
    return;
  }

  toggleCheckbox.disabled = false;
  toggleCheckbox.checked = status.isEnabled;
  colorModeCheckbox.disabled = false;
  colorModeCheckbox.checked = status.colorMode;

  if (!status.isJapanesePage) {
    statusElement.textContent = '日本語のページではありません';
    statusElement.className = 'status inactive';
    toggleCheckbox.disabled = true;
    colorModeCheckbox.disabled = true;
  } else if (status.isProcessing) {
    statusElement.textContent = '処理中...';
    statusElement.className = 'status';
  } else if (status.isEnabled) {
    if (status.processedCount > 0) {
      statusElement.textContent = `有効 (${status.processedCount}箇所を処理)`;
    } else {
      statusElement.textContent = '有効';
    }
    statusElement.className = 'status active';
  } else {
    statusElement.textContent = '無効';
    statusElement.className = 'status inactive';
  }
}

/**
 * 获取当前 tab
 */
async function getCurrentTab(): Promise<chrome.tabs.Tab | null> {
  const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
  return tabs[0] || null;
}

/**
 * 向 content script 发送消息
 */
async function sendToContentScript<T>(tabId: number, message: object): Promise<T> {
  return new Promise((resolve, reject) => {
    chrome.tabs.sendMessage(tabId, message, (response) => {
      if (chrome.runtime.lastError) {
        reject(new Error(chrome.runtime.lastError.message));
      } else {
        resolve(response as T);
      }
    });
  });
}

/**
 * 获取内容脚本状态
 */
async function fetchStatus(): Promise<void> {
  try {
    const tab = await getCurrentTab();

    if (!tab?.id) {
      updateStatusDisplay(null, 'タブが見つかりません');
      return;
    }

    // 检查是否是支持的页面
    if (tab.url?.startsWith('chrome://') || tab.url?.startsWith('chrome-extension://')) {
      updateStatusDisplay(null, 'このページでは使用できません');
      return;
    }

    const status = await sendToContentScript<ContentStatus>(tab.id, { type: 'GET_STATUS' });
    currentStatus = status;
    updateStatusDisplay(status);
  } catch (error) {
    console.error('[Popup] Error fetching status:', error);
    updateStatusDisplay(null, 'ページに接続できません');
  }
}

/**
 * 切换启用状态
 */
async function toggleEnabled(enabled: boolean): Promise<void> {
  try {
    const tab = await getCurrentTab();

    if (!tab?.id) {
      return;
    }

    updateStatusDisplay({ ...currentStatus!, isProcessing: true });

    const response = await sendToContentScript<{ success: boolean; isEnabled: boolean; error?: string }>(
      tab.id,
      { type: 'TOGGLE_ENABLED', enabled }
    );

    if (response.success) {
      await fetchStatus();
    } else {
      console.error('[Popup] Toggle failed:', response.error);
      updateStatusDisplay(null, 'エラーが発生しました');
    }
  } catch (error) {
    console.error('[Popup] Error toggling:', error);
    updateStatusDisplay(null, 'エラーが発生しました');
  }
}

/**
 * 切换彩色模式
 */
async function toggleColorMode(enabled: boolean): Promise<void> {
  try {
    const tab = await getCurrentTab();

    if (!tab?.id) {
      return;
    }

    const response = await sendToContentScript<{ success: boolean; colorMode: boolean; error?: string }>(
      tab.id,
      { type: 'TOGGLE_COLOR_MODE', colorMode: enabled }
    );

    if (response.success) {
      await fetchStatus();
    } else {
      console.error('[Popup] Color mode toggle failed:', response.error);
    }
  } catch (error) {
    console.error('[Popup] Error toggling color mode:', error);
  }
}

/**
 * 读音查询
 */
async function lookupReading(): Promise<void> {
  const text = lookupInput.value.trim();

  if (!text) {
    return;
  }

  lookupResult.classList.add('show');
  lookupResult.innerHTML = '<span class="loading">読み込み中...</span>';
  lookupBtn.disabled = true;

  try {
    const tab = await getCurrentTab();

    if (!tab?.id) {
      lookupResult.innerHTML = '<span class="error">タブが見つかりません</span>';
      return;
    }

    // 检查是否是支持的页面
    if (tab.url?.startsWith('chrome://') || tab.url?.startsWith('chrome-extension://')) {
      lookupResult.innerHTML = '<span class="error">このページでは使用できません</span>';
      return;
    }

    const response = await sendToContentScript<{
      success: boolean;
      tokens?: Array<{
        surface: string;
        reading: string;
        needsRuby: boolean;
        pos: string;
      }>;
      error?: string;
    }>(tab.id, { type: 'TOKENIZE_TEXT', text });

    if (response.success && response.tokens) {
      // 构建带假名的 HTML
      let html = '';
      for (const token of response.tokens) {
        if (token.needsRuby && token.reading) {
          html += `<span class="token"><ruby>${escapeHtml(token.surface)}<rt>${escapeHtml(token.reading)}</rt></ruby></span>`;
        } else {
          html += `<span class="token">${escapeHtml(token.surface)}</span>`;
        }
      }
      lookupResult.innerHTML = html || '<span class="error">結果がありません</span>';
    } else {
      lookupResult.innerHTML = `<span class="error">${response.error || 'エラーが発生しました'}</span>`;
    }
  } catch (error) {
    console.error('[Popup] Lookup error:', error);
    lookupResult.innerHTML = '<span class="error">ページに接続できません</span>';
  } finally {
    lookupBtn.disabled = false;
  }
}

/**
 * HTML 转义
 */
function escapeHtml(text: string): string {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

/**
 * 加载读音字典
 */
async function loadReadingDict(): Promise<Record<string, string[]>> {
  if (readingDict) {
    return readingDict;
  }

  const url = chrome.runtime.getURL('data/reading_dict.json');
  const response = await fetch(url);
  readingDict = await response.json();
  return readingDict!;
}

/**
 * 片假名转平假名
 */
function katakanaToHiragana(str: string): string {
  return str.replace(/[\u30A1-\u30F6]/g, (match) => {
    return String.fromCharCode(match.charCodeAt(0) - 0x60);
  });
}

/**
 * 逆引き検索
 */
async function reverseLookup(): Promise<void> {
  let text = reverseInput.value.trim();

  if (!text) {
    return;
  }

  // 将片假名转为平假名
  text = katakanaToHiragana(text);

  reverseResult.classList.add('show');
  reverseResult.innerHTML = '<span class="loading">検索中...</span>';
  reverseBtn.disabled = true;

  try {
    const dict = await loadReadingDict();
    const results = dict[text];

    if (results && results.length > 0) {
      const html = results.map(item => `<span class="kanji-item">${escapeHtml(item)}</span>`).join('');
      reverseResult.innerHTML = html;
    } else {
      reverseResult.innerHTML = '<span class="no-result">結果が見つかりませんでした</span>';
    }
  } catch (error) {
    console.error('[Popup] Reverse lookup error:', error);
    reverseResult.innerHTML = '<span class="error">辞書の読み込みに失敗しました</span>';
  } finally {
    reverseBtn.disabled = false;
  }
}

// 事件监听
toggleCheckbox.addEventListener('change', () => {
  toggleEnabled(toggleCheckbox.checked);
});

colorModeCheckbox.addEventListener('change', () => {
  toggleColorMode(colorModeCheckbox.checked);
});

lookupBtn.addEventListener('click', () => {
  lookupReading();
});

lookupInput.addEventListener('keypress', (e) => {
  if (e.key === 'Enter') {
    lookupReading();
  }
});

reverseBtn.addEventListener('click', () => {
  reverseLookup();
});

reverseInput.addEventListener('keypress', (e) => {
  if (e.key === 'Enter') {
    reverseLookup();
  }
});

// 初始化
document.addEventListener('DOMContentLoaded', () => {
  fetchStatus();
});
